//! Instruction counts of Connect Four (ADR-0025 PR gate, gungraun): one
//! full pool step (masks, the acting update and the turn check, auto-reset
//! on) and the pinned P2-G1 bot's choice on a fixed set of positions.
//! Setup runs outside the measured region, and the benchmarks return their
//! inputs so that dropping them is not counted either. Linux only
//! (Valgrind); see `make gungraun`.

#![expect(clippy::unwrap_used, reason = "bench setup unwraps")]
#![expect(missing_docs, reason = "items generated by the gungraun macros")]

use core::num::NonZeroU32;
use std::hint::black_box;

use gungraun::{
    Callgrind, CallgrindMetrics, LibraryBenchmarkConfig, library_benchmark,
    library_benchmark_group, main,
};
use tessera_rl_engine::{ActionInput, EnvPool, Masked, PoolOptions, Reseed};
use tessera_rl_games::connect4::board::can_play;
use tessera_rl_games::connect4::bot::{Bot, TIE_BASE};
use tessera_rl_games::{Connect4, Connect4Config, Connect4State};
use tessera_rl_num::identity::Seed;

/// A Connect Four pool advanced 10 plies (mid-game boards, some games
/// already restarted), and one batch of columns (full ones become the
/// no-op).
fn connect4(n: u32) -> (EnvPool<Connect4, Masked>, Vec<i32>) {
    let options = PoolOptions::new(NonZeroU32::new(n).unwrap(), Seed::new(1));
    let mut pool = EnvPool::with_masks(Connect4Config {}, options).unwrap();
    pool.reset_all(Reseed::Keep).unwrap();
    let rows = pool.outputs().rewards().len();
    let batch = |k: usize| -> Vec<i32> {
        (0..rows)
            .map(|i| i32::try_from((i * 3 + k * 5) % 7).unwrap())
            .collect()
    };
    for k in 0..10 {
        let acts = batch(k);
        pool.step(ActionInput {
            discrete: &acts,
            continuous: &[],
        })
        .unwrap();
    }
    (pool, batch(10))
}

/// `n` mid-game positions: plies `8 + (i % 13)` of a fixed column pattern,
/// skipping columns that are full.
fn positions(n: usize) -> Vec<Connect4State> {
    (0..n)
        .map(|i| {
            let mut s = Connect4State::default();
            for k in 0..8 + i % 13 {
                let mut col = u32::try_from((i * 5 + k * 3 + k * k) % 7).unwrap();
                while !can_play(s.occupied(), col) {
                    col = (col + 1) % 7;
                }
                s.play(col);
                if s.is_over() {
                    break;
                }
            }
            s
        })
        .filter(|s| !s.is_over())
        .collect()
}

#[library_benchmark]
#[bench::n1024(setup = connect4, args = (1024))]
fn connect4_pool_step(
    (mut pool, actions): (EnvPool<Connect4, Masked>, Vec<i32>),
) -> (EnvPool<Connect4, Masked>, Vec<i32>) {
    let out = pool
        .step(ActionInput {
            discrete: black_box(&actions),
            continuous: &[],
        })
        .unwrap();
    black_box(out.rewards().first().copied());
    (pool, actions)
}

#[library_benchmark]
#[bench::positions_32(setup = positions, args = (32))]
fn bot_choose(states: Vec<Connect4State>) -> Vec<Connect4State> {
    let bot = Bot::new(TIE_BASE);
    for s in &states {
        black_box(bot.choose(black_box(s)));
    }
    states
}

library_benchmark_group!(name = games, benchmarks = [connect4_pool_step, bot_choose]);

/// The glibc dispatch pin of every instruction-count run.
const GLIBC_TUNABLES: &str = include_str!("../../../benches/gungraun/GLIBC_TUNABLES");

/// Callgrind with the cache simulation on (instruction counts and cache
/// misses, ADR-0025). The gate, a 2% limit on `Ir`, is passed by
/// `scripts/gungraun.sh`; the cache metrics are reported.
fn config() -> LibraryBenchmarkConfig {
    let mut config = LibraryBenchmarkConfig::default();
    // glibc picks memcpy and memset variants by CPU (ifunc), which would
    // make the counts depend on the machine: pin them to the baseline
    // variants (benches/gungraun/README.md).
    config.env("GLIBC_TUNABLES", GLIBC_TUNABLES.trim());
    config.tool(
        // A fixed cache geometry, so cache metrics compare across hosts.
        Callgrind::with_args([
            "--cache-sim=yes",
            "--I1=32768,8,64",
            "--D1=32768,8,64",
            "--LL=8388608,16,64",
        ])
        .format([CallgrindMetrics::All]),
    );
    config
}

main!(config = config(), library_benchmark_groups = games);
